def solve(graph,start):
 d=[-1]*len(graph)
 d[start]=0
 queue=[start]
 for u in queue:
  for v in graph[u]:
   if d[v]==-1: d[v]=d[u]+1; queue.append(v)
 return [max(0,x) for x in d]

def solve(graph,start):
 d=[-1]*len(graph)
 d[start]=0
 stack=[start]
 while stack:
  u=stack.pop()
  for v in graph[u]:
   if d[v]==-1: d[v]=d[u]+1; stack.append(v)
 return d

